 "content": "def transform(grid):
    out = [row[:] for row in grid]
    anchors = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(anchors) != 2:
        return out

    # The source 5 is embedded in a colored pattern; the destination 5 is isolated.
    def surrounding_count(anchor):
        r0, c0 = anchor
        return sum(
            1
            for r, row in enumerate(grid)
            for c, value in enumerate(row)
            if value != 0 and value != 5 and (r, c) != anchor
        )

    source = max(anchors, key=surrounding_count)
    target = anchors[0] if anchors[1] == source else anchors[1]
    sr, sc = source
    tr, tc = target
    out[tr][tc] = 0
    dr, dc = tr - sr, tc - sc
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 0 or (r, c) == source or (r, c) == target:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(row):
                out[nr][nc] = value
    return out
